"""Execute real storage loading/uninstall: total accounting, permission fallback, sorting and delete guards."""
from pathlib import Path
import subprocess,tempfile
files={
'android/app/AppOpsManager.java':'package android.app;public class AppOpsManager{public static final String OPSTR_GET_USAGE_STATS="usage";public static final int MODE_ALLOWED=0;public static boolean allowed;public int checkOpNoThrow(String op,int uid,String pkg){return allowed?0:1;}}',
'android/app/usage/StorageStats.java':'package android.app.usage;public class StorageStats{long app,data;public StorageStats(long a,long d){app=a;data=d;}public long getAppBytes(){return app;}public long getDataBytes(){return data;}public long getCacheBytes(){throw new AssertionError("cache double counted");}}',
'android/app/usage/StorageStatsManager.java':'package android.app.usage;public class StorageStatsManager{public StorageStats queryStatsForPackage(java.util.UUID uuid,String pkg,android.os.UserHandle u){if(!android.app.AppOpsManager.allowed||pkg.endsWith("unknown"))throw new SecurityException();return pkg.endsWith("large")?new StorageStats(200,300):new StorageStats(10,20);}}',
'android/os/Process.java':'package android.os;public class Process{public static int myUid(){return 101234;}}',
'android/os/UserHandle.java':'package android.os;public class UserHandle{public static UserHandle getUserHandleForUid(int uid){return new UserHandle();}}',
'android/os/storage/StorageManager.java':'package android.os.storage;public class StorageManager{public static final java.util.UUID UUID_DEFAULT=new java.util.UUID(0,0);}',
'android/content/pm/ApplicationInfo.java':'package android.content.pm;public class ApplicationInfo{public static final int FLAG_SYSTEM=1;public int flags,uid=101234;public String packageName;public java.util.UUID storageUuid;public ApplicationInfo(String p,int f){packageName=p;flags=f;}public CharSequence loadLabel(PackageManager pm){return packageName;}}',
'android/content/pm/PackageManager.java':'package android.content.pm;import java.util.*;public class PackageManager{public static final int MATCH_DISABLED_COMPONENTS=512;public List<ApplicationInfo> apps=new ArrayList<>();public List<ApplicationInfo> getInstalledApplications(int f){return apps;}public ApplicationInfo getApplicationInfo(String p,int f){for(ApplicationInfo a:apps)if(a.packageName.equals(p))return a;throw new IllegalArgumentException();}}',
'android/content/Context.java':'package android.content;public class Context{public android.content.pm.PackageManager pm=new android.content.pm.PackageManager();public String getPackageName(){return "io.tvos";}public android.content.pm.PackageManager getPackageManager(){return pm;}public <T>T getSystemService(Class<T> type){try{return type.getDeclaredConstructor().newInstance();}catch(Exception e){throw new IllegalStateException(e);}}}',
'io/tvos/Adb.java':'package io.tvos;class Adb implements AutoCloseable{static boolean fail;static int calls;static String command;static Adb connect(Object c,int wait,Runnable ready){if(fail)throw new IllegalStateException();return new Adb();}String shell(String text){calls++;command=text;if(text.startsWith("appops ")){android.app.AppOpsManager.allowed=true;return "";}return "Success\\n";}public void close(){}}',
'io/tvos/AppLog.java':'package io.tvos;class AppLog{static void w(String s){}}',
}
files['io/tvos/StorageApps.java']=Path('app/src/io/tvos/StorageApps.java').read_text()
files['android/net/Uri.java']='package android.net;public class Uri{public String value;public static Uri fromParts(String scheme,String pkg,String fragment){Uri u=new Uri();u.value=scheme+":"+pkg;return u;}}'
files['android/content/Intent.java']='package android.content;public class Intent{public static final String ACTION_UNINSTALL_PACKAGE="uninstall",EXTRA_RETURN_RESULT="return-result";public String action;public android.net.Uri uri;public boolean result;public Intent(String a,android.net.Uri u){action=a;uri=u;}public Intent putExtra(String k,boolean v){result=v;return this;}}'
files['io/tvos/Test.java']='''package io.tvos;import android.content.*;import android.content.pm.*;import java.util.*;class Test{static void check(boolean b,String s){if(!b)throw new AssertionError(s);}public static void main(String[] args){Context c=new Context();c.pm.apps.add(new ApplicationInfo("io.tvos",0));c.pm.apps.add(new ApplicationInfo("com.example.small",0));c.pm.apps.add(new ApplicationInfo("com.example.large",0));c.pm.apps.add(new ApplicationInfo("com.example.unknown",0));c.pm.apps.add(new ApplicationInfo("com.system.protected",1));List<StorageApps.Item> items=StorageApps.load(c);check(Adb.calls==1&&Adb.command.equals("appops set --user 1 io.tvos GET_USAGE_STATS allow"),"grant usage access only for the launcher user via existing ADB");check(items.size()==4&&items.get(0).pkg.equals("com.example.large")&&items.get(0).bytes==500,"total code + data without double cache, sorted largest first");check(items.get(3).bytes==-1,"unknown stays unknown");check(items.stream().anyMatch(i->i.pkg.equals("io.tvos")&&!i.removable),"launcher protected");int calls=Adb.calls;StorageApps.load(c);check(calls==Adb.calls,"granted access not reconfigured");check(StorageApps.uninstallIntent(c,"io.tvos")==null&&StorageApps.uninstallIntent(c,"com.system.protected")==null&&StorageApps.uninstallIntent(c,"com.example.app;reboot")==null,"self, system, malformed packages denied");Intent request=StorageApps.uninstallIntent(c,"com.example.small");check(request!=null&&request.action.equals(Intent.ACTION_UNINSTALL_PACKAGE)&&request.uri.value.equals("package:com.example.small")&&request.result,"native uninstall intent targets selected package and returns result");check(calls==Adb.calls,"no shell uninstall or silent deletion");android.app.AppOpsManager.allowed=false;Adb.fail=true;items=StorageApps.load(c);check(items.size()==4&&items.stream().allMatch(i->i.bytes==-1),"statistics failure preserves list");check(StorageApps.uninstallIntent(c,"com.example.small")!=null,"native uninstall does not depend on ADB");System.out.println("PASS: actual storage totals, ordering, unknown sizes, protected packages and native uninstall intent");}}'''
with tempfile.TemporaryDirectory() as tmp:
 root=Path(tmp)
 for name,source in files.items():
  p=root/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(source)
 subprocess.run(['java','com.sun.tools.javac.Main','-source','8','-target','8','-Xlint:all,-options','-Werror','-d',tmp,*map(str,root.rglob('*.java'))],check=True)
 subprocess.run(['java','-cp',tmp,'io.tvos.Test'],check=True)
